import sys
input = sys.stdin.read().split()
n = int(input[0])
m = int(input[1])
constraints = [(int(input[3*i+2]), int(input[3*i+3]), int(input[3*i+4])) for i in range(m)]
a = [0] * n
for li, ri, qi in constraints:
    for j in range(li-1, ri):
        a[j] |= qi
for li, ri, qi in constraints:
    for j in range(ri-1, li-2, -1):
        a[j] &= qi
for li, ri, qi in constraints:
    if qi != a[li-1] & a[ri-1]:
        print("NO")
        exit()
print("YES")
print(" ".join(map(str, a)))
